#!/usr/bin/env bash
# The hero's background razor (R19): an AI photo of an open straight razor on pure black,
# generated by the user with Nano Banana (prompt in docs/specs/001-reservas/imagenes.md).
# Its light becomes the alpha channel of a flat bone (--hueso) image, so the razor sits on the
# charcoal hero with a transparent ground and no blend mode; the page sets how faint it is.
# The black is clipped a little first, so the photo's near-black ground turns fully clear.
# Usage: scripts/navaja-hero.sh <original> src/assets/fotos/hero-navaja.webp
set -euo pipefail
original="$1"
salida="$2"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

magick "$original" -resize '1600x>' -colorspace gray -level 8%,100% "$tmp/luz.png"
magick \( "$tmp/luz.png" -fill '#ede6d8' -colorize 100 \) "$tmp/luz.png" \
  -alpha off -compose CopyOpacity -composite -strip -quality 82 "$salida"
